/*
 Problem: 1541. Minimum Insertions to Balance a Parentheses String
 Language: cpp
 Runtime: 3 ms (81.54%)
 Memory: 15.5 MB (75.44%)
 Tags: String, Stack, Greedy, Bracket Sequences
*/

class Solution {
public:
    int minInsertions(string s) {
        int ans = 0, need = 0;

        for (char c : s) {
            if (c == '(') {
                need += 2;

                if (need % 2) {
                    ++ans;
                    --need;
                }
            } else {
                --need;

                if (need < 0) {
                    ++ans;
                    need = 1;
                }
            }
        }

        return ans + need;
    }
};
